preToolUse.powershell:
$p = [Console]::In.ReadToEnd()
function Deny([string]$why) { [Console]::Out.WriteLine('{"permissionDecision":"deny","permissionDecisionReason":"Blocked by the Copilot kit deny hook: ' + $why + '"}'); exit 0 }
function Has([string]$re) { return [regex]::IsMatch($p, $re, [System.Text.RegularExpressions.RegexOptions]::Multiline) }
if (-not (Has '"toolName"\s*:\s*"(view|create|edit|str_replace_editor|apply_patch)"')) {
if (Has 'git push[^"]*(--force([^-]|$)|\s-f("|\s|$))') { Deny 'force-push rewrites shared history; use --force-with-lease on your own branch' }
if (Has 'git reset[^"]*--hard') { Deny 'git reset --hard discards uncommitted work; commit or use git stash' }
if (Has 'rm\s+-[a-zA-Z]*(rf|fr)[a-zA-Z]*\s+(/|~/?|\$HOME/?|\./?|\.\./?|\*)("|\s|;|&|$)') { Deny 'rm -rf on a root, home or whole working directory' }
}
if (Has '\.env("|\s|$)') { Deny 'reading or writing .env files can leak secrets; use .env.example' }
if (Has '(\.pem|\.key|id_rsa|id_ed25519|id_ecdsa)("|\s|$)') { Deny 'private key files are off limits' }
exit 0
